import{_ as a,c as t,o,aj as r}from"./chunks/framework.BlveriQe.js";const p=JSON.parse('{"title":"Interface: DocumentFormatMismatchEvent","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/DocumentFormatMismatchEvent.md","filePath":"reference/js-bao-wss-client/api/interfaces/DocumentFormatMismatchEvent.md"}'),c={name:"reference/js-bao-wss-client/api/interfaces/DocumentFormatMismatchEvent.md"};function n(d,e,s,i,l,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / DocumentFormatMismatchEvent</p><h1 id="interface-documentformatmismatchevent" tabindex="-1">Interface: DocumentFormatMismatchEvent <a class="header-anchor" href="#interface-documentformatmismatchevent" aria-label="Permalink to “Interface: DocumentFormatMismatchEvent”">​</a></h1><p>Payload of the <code>document:format-mismatch</code> event (<code>client.on(&quot;document:format-mismatch&quot;, ...)</code>).</p><p>Fired when the platform refuses a document because the format this client believed it had is not the format the platform resolved. The document is CLOSED when this arrives — its local rows and its unacknowledged writes are kept, nothing is evicted — because two of the three open shapes have no waiter to reject: a cached open sends its handshake from a microtask, and an already-open document re-syncs on reconnect. An open that WAS waiting on the network rejects with the same error as well.</p><p>Diagnose from <a href="#declared">declared</a> and <a href="#actual">actual</a> before doing anything: the server also logs <code>Document format disagreement</code> naming its own pinned format. Evicting the document clears this client&#39;s belief, which repairs a stale row and HIDES a mis-pinned document.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="actual" tabindex="-1">actual <a class="header-anchor" href="#actual" aria-label="Permalink to “actual”">​</a></h3><blockquote><p><strong>actual</strong>: <code>1</code> | <code>2</code></p></blockquote><p>What the platform resolved for the document.</p><hr><h3 id="declared" tabindex="-1">declared <a class="header-anchor" href="#declared" aria-label="Permalink to “declared”">​</a></h3><blockquote><p><strong>declared</strong>: <code>1</code> | <code>2</code></p></blockquote><p>What this client believed, from its own local metadata row.</p><hr><h3 id="documentid" tabindex="-1">documentId <a class="header-anchor" href="#documentid" aria-label="Permalink to “documentId”">​</a></h3><blockquote><p><strong>documentId</strong>: <code>string</code></p></blockquote><hr><h3 id="error" tabindex="-1">error <a class="header-anchor" href="#error" aria-label="Permalink to “error”">​</a></h3><blockquote><p><strong>error</strong>: <a href="./../classes/JsBaoError.html"><code>JsBaoError</code></a></p></blockquote><p>The very error a waiting <code>documents.open</code> rejects with: <code>code</code> is <code>DOCUMENT_FORMAT_MISMATCH</code> and <code>details</code> carries <code>documentId</code>, <code>declared</code> and <code>actual</code>.</p>',22)])])}const u=a(c,[["render",n]]);export{p as __pageData,u as default};
